// `@apply` only takes utilities in Tailwind v4, so the shared building blocks are declared as such.
@utility input-disable {
  @apply bg-layer-3 text-secondary;
}

@utility base-button {
  @apply flex flex-row items-center px-3 py-2;
  @apply rounded border border-solid border-transparent text-sm;

  min-width: 38px;
  min-height: 38px;
}

@utility base-button-disable {
  @apply pointer-events-none text-controls-disable bg-controls-disable;
}

// Shared by `.input` and by the AG Grid fields that look like it: `@apply` cannot take a class in Tailwind v4.
@mixin input-field {
  @apply border border-solid border-primary rounded outline-0;
  @apply bg-transparent text-sm truncate;
  @apply px-3 py-2;

  &:not(:placeholder-shown) {
    @apply text-primary;
  }

  &:hover {
    @apply border-hover;
  }

  &:focus,
  &:focus-within {
    @apply border-accent-primary;
  }

  &:disabled {
    @apply bg-layer-3 text-secondary;
  }
}

// Same reason as `input-field`: the grid buttons reuse these through `@include`.
@mixin button-primary {
  @apply base-button bg-controls-accent text-controls-primary;

  &:hover,
  &:focus {
    @apply bg-controls-accent-hover;
  }

  &:focus {
    @apply border-hover;
  }
}

@mixin button-secondary {
  @apply base-button bg-transparent text-primary;
  @apply border-primary;

  &:hover,
  &:focus {
    @apply bg-layer-4;
  }

  &:focus {
    @apply border-hover;
  }

  &:disabled {
    @apply base-button-disable;
  }
}

@layer components {
  // TODO: remove after fixing style in UI kit
  .input {
    @include input-field;
  }

  .primary {
    @include button-primary;
  }

  .secondary {
    @include button-secondary;
  }
}

// The file manager grid is framed by a 1px border with an 8px radius (replaces the library's rounded-xl + shadow).
.file-manager-grid {
  @apply border border-solid border-tertiary rounded-lg overflow-hidden !shadow-none;
}

// The file manager grid design draws row dividers at half weight (header divider stays 1px).
.file-manager-grid .ag-root-wrapper .ag-row {
  border-bottom-width: 0.5px;
}

.ag-root-wrapper {
  .ag-row {
    @apply border-b border-tertiary;
  }

  .ag-root-wrapper-body {
    @apply h-auto;
  }

  .ag-filter-wrapper {
    .ag-input-field-input.ag-text-field-input,
    .ag-input-field-input.ag-number-field-input,
    .ag-picker-field-wrapper.ag-picker-collapsed,
    .ag-picker-field-wrapper.ag-picker-expanded {
      @include input-field;
    }

    .ag-input-field-input.ag-text-field-input,
    .ag-input-field-input.ag-input-field-input {
      @apply pl-5;
    }

    .ag-filter-apply-panel-button.ag-button {
      @apply base-button;
      &[data-ref='applyFilterButton'] {
        @include button-primary;
      }

      &[data-ref='resetFilterButton'] {
        @include button-secondary;
      }
    }
  }

  @apply overflow-x-auto;
  .ag-header {
    @apply border-b border-tertiary;
    .ag-header-cell.align-right {
      .ag-header-cell-label {
        @apply justify-end;
      }
    }
    .ag-header-viewport,
    .ag-pinned-left-header {
      .ag-floating-filter {
        input {
          @include input-field;
          @apply m-0 p-0 px-2;
          height: 24px !important;
        }
      }
      // A filter row with no input (see EmptyFloatingFilter): drop the empty body so the button
      // centres in the cell instead of hanging off its right edge.
      .ag-floating-filter:has(.ag-grid-filter-button-only) {
        .ag-floating-filter-body {
          @apply hidden;
        }

        .ag-floating-filter-button {
          @apply flex h-full w-full items-center justify-center;
          margin: 0;
        }
      }
    }
  }

  .ag-cell {
    user-select: text;
    @apply flex items-center;
    &.ag-grid-no-border,
    &.ag-cell-focus {
      @apply border-0;
    }

    &.column-divider:not(:last-child) {
      @apply border-0 border-r border-solid border-tertiary;
    }

    &.align-right {
      @apply justify-end;
    }
  }
  .ag-cell.ag-cell-first-right-pinned:not(
      .ag-cell-range-left,
      .ag-cell-range-single-cell,
      .ag-cell-focus:not(.ag-cell-range-selected):focus-within
    ) {
    @apply border-0;
  }
  .ag-error-row {
    @apply bg-error;
    #editable-cell-renderer {
      @apply border-error;
    }
    &.ag-error-border {
      @apply border border-error;
      @apply cursor-pointer;
    }
    &.ag-row-hover:not(.ag-full-width-row):before {
      @apply bg-transparent;
    }
  }
  .ag-new-row {
    @apply bg-success;
    &.ag-new-border {
      @apply border border-accent-secondary;
      @apply cursor-pointer;
    }
    &.ag-row-hover:not(.ag-full-width-row):before {
      @apply bg-transparent;
    }
  }
  .ag-changed-row {
    @apply bg-info;
    &.ag-changed-border {
      @apply border border-accent-primary;
      @apply cursor-pointer;
    }
    &.ag-row-hover:not(.ag-full-width-row):before {
      @apply bg-transparent;
    }
  }
  .ag-empty-row {
    &.ag-row-hover:not(.ag-full-width-row):before {
      @apply bg-transparent;
    }
  }
  // The `.ag-grid-no-border` variants outrank the border reset score cells carry, so the diff box survives it.
  .ag-cell.compare-metric-improved-start,
  .ag-cell.ag-grid-no-border.compare-metric-improved-start {
    @apply border-solid border-l border-t border-b border-accent-secondary border-r-0;
  }
  .ag-cell.compare-metric-improved-end,
  .ag-cell.ag-grid-no-border.compare-metric-improved-end {
    @apply border-solid border-t border-b border-r border-accent-secondary border-l-0;
  }
  .ag-cell.compare-metric-regressed-start,
  .ag-cell.ag-grid-no-border.compare-metric-regressed-start {
    @apply border-solid border-l border-t border-b border-error border-r-0;
  }
  .ag-cell.compare-metric-regressed-end,
  .ag-cell.ag-grid-no-border.compare-metric-regressed-end {
    @apply border-solid border-t border-b border-r border-error border-l-0;
  }
  .ag-cell.compare-metric-new-start,
  .ag-cell.ag-grid-no-border.compare-metric-new-start {
    @apply border-solid border-l border-t border-b border-accent-primary border-r-0;
  }
  .ag-cell.compare-metric-new-end,
  .ag-cell.ag-grid-no-border.compare-metric-new-end {
    @apply border-solid border-t border-b border-r border-accent-primary border-l-0;
  }
  .ag-active-detail-row {
    @apply bg-controls-accent-alpha;
    &.ag-row-hover:not(.ag-full-width-row):before {
      @apply bg-transparent;
    }
  }
  .ag-activity-row-clickable {
    cursor: pointer;
  }
  .ag-row-selected {
    @apply bg-controls-accent-alpha;
    &.ag-row-hover:not(.ag-full-width-row):before {
      @apply bg-transparent;
    }
  }
}

.ag-grid-no-checkbox {
  .ag-selection-checkbox {
    @apply hidden;
  }
}

.ag-selection-checkbox {
  height: 100% !important;
}

.ag-checkbox-input-wrapper {
  @apply block;
  @apply w-[18px] h-[18px];
  @apply border-hover shadow-none;
  &::after {
    @apply hidden;
  }

  &.ag-checked {
    @apply border-accent-primary;
    @apply bg-transparent bg-center bg-no-repeat;
    background-image: url(/images/icons/checkmark.svg);
  }

  &.ag-indeterminate {
    @apply border-accent-primary;
    @apply bg-transparent bg-center bg-no-repeat;
    background-image: url(/images/icons/indeterminate.svg);
  }

  &:where(:focus-within, :focus, :active) {
    box-shadow: none !important;
  }
}

.ag-layout-auto-height {
  .ag-center-cols-container,
  .ag-center-cols-viewport {
    @apply min-h-0;
  }
}

// AG Grid's native `tooltipValueGetter` bubble is themed from the grid (bordered, grid colours); the
// element qualifier outranks its single-class rule so it matches the ui-kit tooltip instead.
// `break-words` wraps an unbroken token (a JSON value, an id) inside the max width instead of clipping it.
div.ag-tooltip {
  @apply bg-control-inverted text-control-inverted border-0 rounded-lg px-3 py-2 shadow-xs max-w-[376px] break-words;
  font-size: 14px;
  line-height: 20px;
}

// Heat-map tooltips render in AG Grid's popup parent (often outside `.heat-map-grid`).
// When anchored above a cell, move the caret under the body (via order — Tailwind's
// `flex-col` would otherwise win over `flex-direction: column-reverse`) and flip it.
.heat-map-tooltip--above {
  .heat-map-cell-tooltip-body {
    order: 1;
  }

  .heat-map-cell-tooltip-arrow {
    order: 2;
    margin-top: -1px;
    margin-bottom: 0;

    .tooltip-arrow {
      transform: rotate(180deg);
    }
  }
}

.heat-map-grid {
  // Keep AG Grid's internal horizontal scroll usable. overflow:visible on the header
  // viewport breaks scroll sync and clips trailing test-case columns.
  .ag-theme-balham-dark {
    overflow-x: hidden;
  }

  .ag-header-cell.heat-map-test-case-header {
    padding-left: 0 !important;
    padding-right: 0 !important;

    .ag-header-cell-comp-wrapper {
      height: 100%;
      padding-left: 0;
      padding-right: 0;
    }
  }

  .ag-header-cell {
    border-top: none !important;
    border-left: none !important;
    @apply border-r border-b border-tertiary;
  }

  .ag-cell {
    border-top: none !important;
    border-left: none !important;
    @apply border-r border-b border-tertiary;
    padding: 0 !important;
  }

  // The kit wraps the score renderer in a dropdown trigger (`items-center`) and a
  // content-sized span. With the number hidden, that span collapses to the 1px
  // border, so the bucket color never fills the row.
  .ag-cell > .dial-kit-dropdown {
    align-items: stretch;

    > span {
      display: flex;
      height: 100%;
      min-height: 0;
    }
  }

  .ag-body-horizontal-scroll {
    min-height: 12px;
  }
}

// GridView wraps the grid in height: 100%. Auto height must follow the rows instead,
// otherwise the stability heatmap stays inside a fixed viewport and scrolls.
.heat-map-grid--auto-height {
  > .size-full {
    height: auto;
  }
}

.conversations-grid {
  .ag-header-group-cell {
    @apply border-b border-tertiary pt-1.5;
  }

  .ag-header-group-cell-label {
    @apply items-start justify-start;
  }

  .ag-header-cell {
    @apply py-1.5;
  }

  .ag-cell {
    @apply py-2;
  }
}

